def min_operations_to_divisible(n, k, a):
    from collections import Counter

    # Count the frequency of each number in the array
    freq = Counter(a)

    # Check if the product of all numbers is already divisible by k
    if all(freq[i] % k == 0 for i in freq):
        return 0

    # Check if there is a number that is already divisible by k
    for i in freq:
        if freq[i] % k == 0:
            return 0

    # Check if there is a number that is divisible by k
    for i in freq:
        if i % k == 0:
            return 0

    # If none of the above conditions are met, we need to find the minimum number of operations
    # to make the product of all numbers divisible by k
    operations = 0
    for i in freq:
        if i % k != 0:
            operations += freq[i] % k

    return operations

