def max_alternating_sum(arr):
    if not arr:
        return 0

    max_sum = float('-inf')
    current_sum = arr[0]

    for i in range(1, len(arr)):
        if (arr[i] % 2) != (arr[i-1] % 2):
            current_sum += arr[i]
            max_sum = max(max_sum, current_sum)
        else:
            current_sum = arr[i]

    return max_sum

