def minExtraChar(s, dictionary):
    dp = [0] * (len(s) + 1)
    for i in range(1, len(s) + 1):
        dp[i] = dp[i - 1] + 1
        for j in range(i):
            if s[j:i] in dictionary:
                dp[i] = min(dp[i], dp[j])
    return dp[-1]

def count_good_integers(num1, num2, min_sum, max_sum):
    MOD = 10**9 + 7

    def digit_sum(n):
        return sum(int(digit) for digit in str(n))

    count = 0

    for i in range(int(num1), int(num2) + 1):
        if min_sum <= digit_sum(i) <= max_sum:
            count += 1
            count %= MOD

    return count

def numAdjacentElements(n, queries):
    nums = [0] * n
    answer = []
    for index, color in queries:
        nums[index] = color
        count = 0
        for j in range(n - 1):
            if nums[j] == nums[j + 1] and nums[j] != 0:
                count += 1
        answer.append(count)
    return answer

def minCost(cost, time):
    n = len(cost)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if time[i - 1] >= j:
                dp[i][j] = min(dp[i - 1][j] + cost[i - 1], dp[i - 1][j - 1])
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[n][n]

def minCost(s: str) -> int:
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][0] = i
        dp[0][i] = i

    for i in range(1, n + 1):
        for j in range(1, i + 1):
            dp[i][j] = min(dp[i - 1][j - 1] + j, dp[i - 1][j] + (n - i))

    return dp[n][n]

def smallest_string(s):
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            new_s = s[:i] + chr(ord(s[i]) - 1) * (j - i + 1) + s[j+1:]
            if new_s < s:
                return new_s
    return s

def special_permutations(nums):
    MOD = 10**9 + 7
    n = len(nums)

    def count_permutations(used, last):
        if len(used) == n:
            return 1
        count = 0
        for i in range(n):
            if not used[i] and (last == -1 or nums[i] % nums[last] == 0 or nums[last] % nums[i] == 0):
                used[i] = True
                count += count_permutations(used, i)
                used[i] = False
        return count

    used = [False] * n
    return count_permutations(used, -1) % MOD

def numWays(nums):
    MOD = 10**9 + 7
    count = 0
    ones = 0
    for num in nums:
        if num == 1:
            ones += 1
        else:
            count += ones
            ones = 0
    count += ones
    return count % MOD

def max_alternating_subarray(nums):
    max_length = -1
    for i in range(len(nums) - 1):
        length = 1
        for j in range(i + 1, len(nums)):
            if (nums[j] - nums[j - 1]) == 1:
                length += 1
            else:
                break
        max_length = max(max_length, length)
    return max_length

def canMakeAllZero(nums, k):
    if k > len(nums):
        return False

    for i in range(len(nums) - k + 1):
        if nums[i] > nums[i + k - 1]:
            return False

    return True

def min_beautiful_substrings(s):
    def is_power_of_5(n):
        if n == 0:
            return False
        while n % 5 == 0:
            n //= 5
        return n == 1

    dp = [float('inf')] * (len(s) + 1)
    dp[0] = 0

    for i in range(1, len(s) + 1):
        for j in range(i):
            if s[j] == '0':
                continue
            if is_power_of_5(int(s[j:i], 2)):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[len(s)] if dp[len(s)] != float('inf') else -1

def minimum_valid_split(nums):
    n = len(nums)
    dominant_element = nums.count(max(nums))

    if dominant_element * 2 > n:
        return -1

    left_count = 0
    for i in range(n - 1):
        if nums[i] == dominant_element:
            left_count += 1
        if left_count * 2 > i + 1:
            return i

    return -1

def maxBeauty(nums, k):
    nums.sort()
    left, right = 0, len(nums) - 1
    max_beauty = 1
    while left <= right:
        if nums[left] + k >= nums[right]:
            max_beauty = max(max_beauty, right - left + 1)
            left += 1
        else:
            right -= 1
    return max_beauty

def maxScore(nums, x):
    if len(nums) == 1:
        return nums[0]

    dp = [0] * len(nums)
    dp[0] = nums[0]

    for i in range(1, len(nums)):
        dp[i] = max(dp[i-1] + nums[i], dp[i-2] + nums[i] - x)

    return dp[-1]

def count_stepping_numbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def is_stepping_number(num: int) -> bool:
        num_str = str(num)
        for i in range(len(num_str) - 1):
            if abs(int(num_str[i]) - int(num_str[i + 1])) != 1:
                return False
        return True

    count = 0
    for i in range(int(low), int(high) + 1):
        if is_stepping_number(i):
            count += 1
            count %= MOD
    return count

def countPairs(coordinates, k):
    count = 0
    for i in range(len(coordinates)):
        for j in range(i + 1, len(coordinates)):
            if (coordinates[i][0] ^ coordinates[j][0]) + (coordinates[i][1] ^ coordinates[j][1]) == k:
                count += 1
    return count

def count_symmetric_integers(low, high):
    def is_symmetric(x):
        s = sum(int(d) for d in str(x))
        return s % 2 == 0 and sum(int(d) for d in str(x)[::-1]) == s

    count = 0
    for i in range(low, high + 1):
        if is_symmetric(i):
            count += 1
    return count

def minAbsDifference(nums, x):
    nums.sort()
    min_diff = float('inf')
    for i in range(len(nums) - x):
        min_diff = min(min_diff, abs(nums[i] - nums[i + x]))
    return min_diff

def countBeautifulIntegers(low, high, k):
    def is_beautiful(n):
        even_count = 0
        odd_count = 0
        while n > 0:
            digit = n % 10
            if digit % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
            n //= 10
        return even_count == odd_count and n % k == 0

    count = 0
    for i in range(low, high + 1):
        if is_beautiful(i):
            count += 1
    return count

