def min_cost_to_equalize(s1, s2, x):
    n = len(s1)
    if s1 != s2:
        return -1

    cost = 0
    i = 0
    while i < n:
        if s1[i] != s2[i]:
            if i + 1 < n and s1[i] == s2[i + 1]:
                cost += 1
                i += 2
            else:
                cost += x
                i += 1
        else:
            i += 1

    return cost

def maxSubarrays(nums):
    count = 0
    current_and = nums[0]
    for i in range(1, len(nums)):
        current_and &= nums[i]
        if current_and == 0:
            count += 1
            current_and = nums[i]
    return count

from collections import Counter

def min_operations(nums):
    count = Counter(nums)
    operations = 0
    for freq in count.values():
        if freq == 1:
            return -1
        elif freq % 3 == 0:
            operations += freq // 3
        elif freq % 3 == 1:
            operations += (freq - 1) // 3 + 1
        else:
            operations += freq // 3
    return operations

def shortest_beautiful_substring(s, k):
    n = len(s)
    min_len = float('inf')
    result = ""

    for i in range(n):
        count = 0
        for j in range(i, n):
            if s[j] == '1':
                count += 1
            if count == k:
                if j - i + 1 < min_len:
                    min_len = j - i + 1
                    result = s[i:j+1]
                elif j - i + 1 == min_len:
                    result = min(result, s[i:j+1])

    return result

def sum_of_squares_of_distinct_counts(nums):
    n = len(nums)
    total_sum = 0

    for i in range(n):
        distinct_count = 0
        distinct_values = set()

        for j in range(i, n):
            if nums[j] not in distinct_values:
                distinct_values.add(nums[j])
                distinct_count += 1

            total_sum += distinct_count ** 2

    return total_sum

def lastVisitedIntegers(words):
    nums = []
    result = []
    prev_count = 0
    for word in words:
        if word == "prev":
            prev_count += 1
            if prev_count > len(nums):
                result.append(-1)
            else:
                result.append(nums[-prev_count])
        else:
            nums.append(int(word))
            prev_count = 0
    return result

def min_changes_to_beautiful(s):
