        if s[i] != s[i+1]:
            changes += 1
    return changes

def minimumSum(nums):
    n = len(nums)
    min_sum = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                if nums[i] < nums[j] and nums[k] < nums[j]:
                    min_sum = min(min_sum, nums[i] + nums[j] + nums[k])
    return min_sum if min_sum != float('inf') else -1

def maxBalancedSubsequenceSum(nums):
    dp = [0] * (len(nums) + 1)
    for i in range(1, len(nums) + 1):
        dp[i] = max(dp[i - 1], dp[i - 2] + nums[i - 1])
    return dp[-1]

def min_steps_to_group_balls(s):
    steps = 0
    ones_count = 0
    for i in range(len(s)):
        if s[i] == '1':
            ones_count += 1
        else:
            steps += ones_count
    return steps

def numGoodStrings(n):
    MOD = 10**9 + 7
    dp = [[0] * (n + 1) for _ in range(5)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(5):
            dp[j][i] = dp[j][i - 1]
            if j > 0:
                dp[j][i] = (dp[j][i] + dp[j - 1][i - 1]) % MOD
            if j < 4:
                dp[j][i] = (dp[j][i] + dp[j + 1][i - 1]) % MOD
    return dp[0][n]

def min_coins(prices):
    n = len(prices)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(i):
            dp[i] = min(dp[i], dp[j] + prices[j])
    return dp[n]

def beautifulSubstrings(s: str, k: int) -> int:
    vowels = set('aeiou')
    count = 0

    for i in range(len(s)):
        vowels_count = 0
        consonants_count = 0
        for j in range(i, len(s)):
            if s[j] in vowels:
                vowels_count += 1
            else:
                consonants_count += 1
            if vowels_count == consonants_count and (vowels_count * consonants_count) % k == 0:
                count += 1

    return count

def num_good_partitions(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        for j in range(i):
            if nums[j] == nums[i - 1]:
                break
            dp[i] = (dp[i] + dp[j]) % MOD

    return dp[n]

def find_peaks(mountain):
    peaks = []
    for i in range(1, len(mountain) - 1):
        if mountain[i] > mountain[i - 1] and mountain[i] > mountain[i + 1]:
            peaks.append(i)
    return peaks

def count_complete_substrings(word, k):
    def is_complete(s):
        from collections import Counter
        count = Counter(s)
        for c in count:
            if count[c] != k:
                return False
        return True

    n = len(word)
    total_count = 0

    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = word[i:j]
            if is_complete(substring):
                total_count += 1

    return total_count

def min_cost_to_equalindromic(nums):
    nums.sort()
    median = nums[len(nums) // 2]
    palindromes = [i for i in range(1, 10**9) if str(i) == str(i)[::-1]]
    min_cost = float('inf')
    for palindrome in palindromes:
        cost = sum(abs(num - palindrome) for num in nums)
        if cost < min_cost:
            min_cost = cost
    return min_cost

def max_partitions(s, k):
    def count_partitions(s, k):
        partitions = 0
        distinct_chars = set()
        for char in s:
            if len(distinct_chars) < k:
                distinct_chars.add(char)
            else:
                if char not in distinct_chars:
                    distinct_chars.add(char)
                    partitions += 1
        return partitions

    max_partitions = count_partitions(s, k)
    for i in range(len(s)):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if s[i] != c:
                new_s = s[:i] + c + s[i+1:]
                max_partitions = max(max_partitions, count_partitions(new_s, k))
    return max_partitions

def count_winning_pairs(n, m):
    count = 0
    for x in range(1, n + 1):
        for y in range(1, m + 1):
            if (x + y) % 2 == 1:
                count += 1
