def max_consecutive_elements(nums):
    nums.sort()
    max_consecutive = 1
    current_consecutive = 1

    for i in range(1, len(nums)):
        if nums[i] == nums[i-1] + 1:
            current_consecutive += 1
        else:
            max_consecutive = max(max_consecutive, current_consecutive)
            current_consecutive = 1

    max_consecutive = max(max_consecutive, current_consecutive)

    return max_consecutive

def max_elements(nums):
    nums.sort()
    count = 0
    i = 0
    while i < len(nums):
        if i + 1 < len(nums) and nums[i] == nums[i + 1]:
            count += 2
            i += 2
        else:
            count += 1
            i += 1
    return count

def count_boundary_crossings(nums):
    boundary_crossed = 0
    current_position = 0
    for num in nums:
        current_position += num
        if current_position == 0:
            boundary_crossed += 1
    return boundary_crossed

def findLengthOfLongestCommonPrefix(arr1, arr2):
    def commonPrefix(a, b):
        while a > 0 and b > 0:
            if a % 10 == b % 10:
                a //= 10
                b //= 10
            else:
                return a
        return 0

    max_length = 0
    for x in arr1:
        for y in arr2:
            max_length = max(max_length, commonPrefix(x, y))
    return max_length

