def generate_sequence(N, A):
    while True:
        modified = False
        for i in range(N - 1):
            if abs(A[i] - A[i + 1]) != 1:
                modified = True
                if A[i] < A[i + 1]:
                    A = A[:i + 1] + list(range(A[i], A[i + 1]))
                else:
                    A = A[:i + 1] + list(range(A[i] - 1, A[i + 1]))
        if not modified:
            break
    return A

