def can_win(S, T):
    # Count the occurrences of each character in S and T
    count_S = {}
    count_T = {}
    for char in S:
        if char != '@':
            count_S[char] = count_S.get(char, 0) + 1
    for char in T:
        if char != '@':
            count_T[char] = count_T.get(char, 0) + 1

    # Check if the counts of each character in S and T are the same
    for char in count_S:
        if count_S[char] != count_T.get(char, 0):
            return "No"

    return "Yes"

