def greatest_value_less_than_or_equal_to_n(S, N):
    T = set()
    for i in range(len(S)):
        if S[i] == '?':
            T.add(int(S[:i] + '0' + S[i+1:], 2))
            T.add(int(S[:i] + '1' + S[i+1:], 2))

    for num in T:
        if num <= N:
            return max(num, key=lambda x: (x > N, x))

    return -1

