def max_candies(H, W, T, grid):
    from collections import deque

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    start = None
    goal = None
    candies = []

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    if start is None or goal is None:
        return -1

    queue = deque([(start[0], start[1], 0, set())])
    visited = set()

    while queue:
        x, y, moves, candies_visited = queue.popleft()

        if (x, y) == goal:
            return len(candies_visited)

        if moves >= T:
            continue

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and (nx, ny) not in visited:
                new_candies_visited = candies_visited.copy()
                if grid[nx][ny] == 'o':
                    new_candies_visited.add((nx, ny))
                queue.append((nx, ny, moves + 1, new_candies_visited))
                visited.add((nx, ny))

    return -1

def find_contiguous_cells(H, W, grid):
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 's':
                for di in range(-1, 2):
                    for dj in range(-1, 2):
                        if di == 0 and dj == 0:
                            continue
                        if grid[i+di][j+dj] == 'n' and grid[i+di+1][j+dj] == 'u' and grid[i+di+2][j+dj] == 'k' and grid[i+di+3][j+dj] == 'e':
                            return (i+di, j+dj), (i+di+1, j+dj), (i+di+2, j+dj), (i+di+3, j+dj), (i+di+4, j+dj)
    return None

