def min_time_to_form_string(X, Y, Z, S):
    n = len(S)
    dp = [[[float('inf')] * 2 for _ in range(n + 1)] for _ in range(n + 1)]
    dp[0][0][0] = 0

    for i in range(n + 1):
        for j in range(n + 1):
            for k in range(2):
                if dp[i][j][k] == float('inf'):
                    continue
                if i + 1 <= n:
                    dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j][k] + X)
                    if k == 0:
                        dp[i + 1][j][1] = min(dp[i + 1][j][1], dp[i][j][k] + X)
                if j + 1 <= n:
                    dp[i][j + 1][k] = min(dp[i][j + 1][k], dp[i][j][k] + Y)
                    if k == 0:
                        dp[i][j + 1][1] = min(dp[i][j + 1][1], dp[i][j][k] + Y)
                if k == 0:
                    dp[i][j][k] = min(dp[i][j][k], dp[i][j][k] + Z)
                if k == 1:
                    dp[i][j][k] = min(dp[i][j][k], dp[i][j][k] + Z)

    return dp[n][n][0]

