def count_ways(N, T, M, incompatible_pairs):
    # Create a graph where each player is a node and an edge between two nodes means they are incompatible
    graph = {i: [] for i in range(1, N+1)}
    for a, b in incompatible_pairs:
        graph[a].append(b)
        graph[b].append(a)

    # Function to check if a team assignment is valid
    def is_valid_team_assignment(team_assignment):
        for a, b in incompatible_pairs:
            if team_assignment[a] == team_assignment[b]:
                return False
        return True

    # Generate all possible team assignments
    from itertools import product
    all_teams = list(product(range(1, T+1), repeat=N))
    valid_team_assignments = [team_assignment for team_assignment in all_teams if is_valid_team_assignment(team_assignment)]

    # Count the number of valid team assignments
    return len(valid_team_assignments)

