def count_holeless_squares(H, W, N, holes):
    # Create a 2D array to store the holed status of each square
    holed = [[False] * (W + 1) for _ in range(H + 1)]

    # Mark the holed squares
    for a, b in holes:
        holed[a][b] = True

    # Initialize the result
    result = 0

    # Iterate over all possible top-left corners of the holeless squares
    for i in range(1, H + 1):
        for j in range(1, W + 1):
            # Iterate over all possible sizes of the holeless squares
            for n in range(1, min(H - i + 1, W - j + 1) + 1):
                # Check if the current square is holeless
                is_holeless = True
                for k in range(n):
                    for l in range(n):
                        if holed[i + k][j + l]:
                            is_holeless = False
                            break
                    if not is_holeless:
                        break

                # If the square is holeless, increment the result
                if is_holeless:
                    result += 1

    return result

