def check_power_of_2_3(N):
    # Check if N is a power of 2 and 3
    if N == 1:
        return "Yes"

    # Check if N is a power of 2
    if N % 2 == 0:
        x = 0
        while N % 2 == 0:
            N //= 2
            x += 1
        if N == 1:
            return "Yes"

    # Check if N is a power of 3
    if N % 3 == 0:
        y = 0
        while N % 3 == 0:
            N //= 3
            y += 1
        if N == 1:
            return "Yes"

    return "No"

