def min_cost_to_monitor_sections(N, D, L, C, K):
    dp = [[[float('inf')] * (K[1] + 1) for _ in range(K[0] + 1)] for _ in range(N + 1)]
    dp[0][0][0] = 0

    for i in range(1, N + 1):
        for j in range(K[0] + 1):
            for k in range(K[1] + 1):
                for l in range(len(L)):
                    if D[i - 1] >= L[l]:
                        dp[i][j][k] = min(dp[i][j][k], dp[i - 1][j][k - 1] + C[l])
                    if j > 0:
                        dp[i][j][k] = min(dp[i][j][k], dp[i - 1][j - 1][k] + C[l])
                    if k > 0:
                        dp[i][j][k] = min(dp[i][j][k], dp[i - 1][j][k - 1] + C[l])

    if dp[N][K[0]][K[1]]:
        return dp[N][K[0]][K[1]]
    else:
        return -1

