def main():
    N, M, K = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(M):
        u, v, w = map(int, sys.stdin.readline().split())
        edges.append((w, u, v))

    # Sort edges by weight
    edges.sort()

    parent = list(range(N+1))
    rank = [0]*(N+1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        x_root = find(x)
        y_root = find(y)
        if x_root == y_root:
            return False
        if rank[x_root] < rank[y_root]:
            parent[x_root] = y_root
        else:
            parent[y_root] = x_root
            if rank[x_root] == rank[y_root]:
                rank[x_root] += 1
        return True

    mst_cost = 0
    for w, u, v in edges:
        if union(u, v):
            mst_cost = (mst_cost + w) % K

    print(mst_cost)

