def min_operations(H, W, A, B):
    def can_transform(A, B):
        if sorted(A) != sorted(B):
            return False

        # Check if we can transform A to B by swapping rows and columns
        for i in range(H):
            for j in range(W):
                if A[i][j] != B[i][j]:
                    return False
        return True

    if not can_transform(A, B):
        return -1

    # Count the number of swaps needed
    swaps = 0
    for i in range(H - 1):
        if A[i] != A[i + 1]:
            swaps += 1
    for j in range(W - 1):
        if A[0][j] != A[0][j + 1]:
            swaps += 1
    return swaps

