import sys
from collections import defaultdict

def find_min_operations(N, edges):
    # Create adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize queue with leaves
    queue = []
    for i in range(1, N+1):
        if len(adj_list[i]) == 1:
            queue.append(i)

    # Perform BFS
    while queue:
        leaf = queue.pop(0)
        for neighbor in adj_list[leaf]:
            adj_list[neighbor].remove(leaf)
            if len(adj_list[neighbor]) == 1:
                queue.append(neighbor)

    return len(queue)

