    potion_count = [0] * (N + 1)
    min_potions = float('inf')
    actions = []

    for t, x in events:
        if t == 1:
            potion_count[x] += 1
            if potion_count[x] > min_potions:
                min_potions = potion_count[x]
                actions = [1] * (x - 1) + [0] + actions
