def cross_product(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def do_intersect(p1, p2, p3, p4):
    o = cross_product(p1, p2, p3) * cross_product(p1, p2, p4)
    c = cross_product(p3, p4, p1) * cross_product(p3, p4, p2)
    d = cross_product(p1, p2, p3) * cross_product(p1, p2, p4)
    return o * d < 0 and c * d < 0

