def main():
    N, M = map(int, sys.stdin.readline().split())
    edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(M)]

    dp = [[sys.maxsize] * (1 << N) for _ in range(N)]
    dp[0][1 << 0] = 0

    for mask in range(1 << N):
        for u in range(N):
            if mask & (1 << u):
                for v, w in edges:
                    if u == v:
                        continue
                    new_mask = mask | (1 << v)
                    dp[v][new_mask] = min(dp[v][new_mask], dp[u][mask] + w)

    result = sys.maxsize
    for u in range(N):
        for v, w in edges:
            if u == v:
                continue
            new_mask = 1 << v
            result = min(result, dp[u][new_mask] + w)

    if result == sys.maxsize:
        print("No")
    else:
        print(result)

