def min_moves_to_meet(N, grid):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N and grid[x][y] != '#'

    def bfs(start1, start2):
        queue = [(start1, start2)]
        visited = set()
        visited.add((start1, start2))

        while queue:
            (x1, y1), (x2, y2) = queue.pop(0)

            if (x1, y1) == (x2, y2):
                return len(queue)

            for dx, dy in directions:
                nx1, ny1 = x1 + dx, y1 + dy
                nx2, ny2 = x2 + dx, y2 + dy

                if is_valid(nx1, ny1) and (nx1, ny1) not in visited:
                    visited.add((nx1, ny1))
                    queue.append(((nx1, ny1), (nx2, ny2)))

                if is_valid(nx2, ny2) and (nx2, ny2) not in visited:
                    visited.add((nx2, ny2))
                    queue.append(((x1, y1), (nx2, ny2)))

        return -1

    start1, start2 = None, None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'P':
                if start1 is None:
                    start1 = (i, j)
                else:
                    start2 = (i, j)

    return bfs(start1, start2)

