def can_place_tiles(N, H, W, tiles):
    grid = [[0] * W for _ in range(H)]

    def place_tile(x, y, a, b):
        for i in range(a):
            for j in range(b):
                grid[x + i][y + j] = 1

    def remove_tile(x, y, a, b):
        for i in range(a):
            for j in range(b):
                grid[x + i][y + j] = 0

    def is_valid(x, y, a, b):
        for i in range(a):
            for j in range(b):
                if grid[x + i][y + j] == 1:
                    return False
        return True

    def backtrack(index):
        if index == N:
            return all(all(cell == 0 for cell in row) for row in grid)

        for a in range(1, H + 1):
            for b in range(1, W + 1):
                if a * b == tiles[index][0] * tiles[index][1]:
                    place_tile(a - 1, b - 1, tiles[index][0], tiles[index][1])
                    if backtrack(index + 1):
                        return True
                    remove_tile(a - 1, b - 1, tiles[index][0], tiles[index][1])
        return False

    return "Yes" if backtrack(0) else "No"

