import math

def find_farthest_point(points):
    N = len(points)
    farthest_points = [0] * N

    for i in range(N):
        max_distance = -1
        farthest_id = -1
        for j in range(N):
            if i != j:
                distance = math.sqrt((points[i][0] - points[j][0])**2 + (points[i][1] - points[j][1])**2)
                if distance > max_distance or (distance == max_distance and j < farthest_id):
                    max_distance = distance
                    farthest_id = j
        farthest_points[i] = farthest_id + 1

    return farthest_points

