    M = 0
    sequences = []
    while L < R:
        l = L
        r = L + 1
        while r < R:
            if (r - l) & (r - 1) == 0:
                sequences.append((l, r))
                L = r
                r += 1
            else:
                r += 1
        M += 1
    return M, sequences

