def check_winner(grid):
    def check_rows(grid):
        for row in grid:
            if row[0] == row[1] == row[2]:
                return row[0]

    def check_cols(grid):
        for col in zip(*grid):
            if col[0] == col[1] == col[2]:
                return col[0]

    def check_diags(grid):
        if grid[0][0] == grid[1][1] == grid[2][2]:
            return grid[0][0]
        if grid[0][2] == grid[1][1] == grid[2][0]:
            return grid[0][2]

    def check_white_cells(grid):
        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    return False
        return True

    def calculate_score(grid):
        score = 0
        for i in range(3):
            for j in range(3):
                if grid[i][j] != 0:
                    score += grid[i][j]
        return score

    def is_game_over(grid):
        if check_rows(grid) != 0 or check_cols(grid) != 0 or check_diags(grid) != 0:
            return True
        if check_white_cells(grid):
            return False
        return True

    def minimax(grid, is_maximizing):
        if is_game_over(grid):
            return calculate_score(grid) if is_maximizing else -calculate_score(grid)

        if is_maximizing:
            best_score = float('-inf')
            for i in range(3):
                for j in range(3):
                    if grid[i][j] == 0:
                        grid[i][j] = 1
                        score = minimax(grid, False)
                        grid[i][j] = 0
                        best_score = max(score, best_score)
            return best_score
        else:
            best_score = float('inf')
            for i in range(3):
                for j in range(3):
                    if grid[i][j] == 0:
                        grid[i][j] = -1
                        score = minimax(grid, True)
                        grid[i][j] = 0
                        best_score = min(score, best_score)
            return best_score

    grid = [[0]*3 for _ in range(3)]
    for i in range(3):
        for j in range(3):
            grid[i][j] = int(input())

    if check_rows(grid) != 0:
        print("Takahashi")
    else:
        print("Aoki")

