def calculate_distances(points):
    N = len(points)
    distances = [[0] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            if i == j:
                distances[i][j] = 0
            else:
                distances[i][j] = min(distances[i][j], distances[i][j-1] + distances[j-1][j])

