def max_degree_of_freedom(H, W, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False] * W for _ in range(H)]
    max_degree = 0

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and not visited[x][y] and grid[x][y] == '.'

    def dfs(x, y):
        stack = [(x, y)]
        visited[x][y] = True
        degree = 1
        while stack:
            cx, cy = stack.pop()
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny):
                    visited[nx][ny] = True
                    stack.append((nx, ny))
                    degree += 1
        return degree

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.' and not visited[i][j]:
                degree = dfs(i, j)
                max_degree = max(max_degree, degree)

    return max_degree

