def find_bingo_turn(N, T, A):
    grid = [[0] * N for _ in range(N)]
    marked = [[False] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            grid[i][j] = N * i + j + 1
            marked[i][j] = True

    for turn in range(T):
        A_i = A[turn]
        i, j = divmod(A_i - 1, N)
        marked[i][j] = True

        # Check rows
        for r in range(N):
            if all(marked[r][j] for j in range(N)):
                return turn + 1

        # Check columns
        for c in range(N):
            if all(marked[r][c] for r in range(N)):
                return turn + 1

        # Check diagonals
        if all(marked[i][i] for i in range(N)):
            return turn + 1
        if all(marked[i][N - 1 - i] for i in range(N)):
            return turn + 1

    return -1

