def findLCP(wordsContainer, wordsQuery):
    def longestCommonSuffix(word1, word2):
        i = 0
        while i < len(word1) and i < len(word2) and word1[i] == word2[i]:
            i += 1
        return i

    result = []
    for query in wordsQuery:
        max_suffix_length = 0
        best_index = -1
        for i, word in enumerate(wordsContainer):
            suffix_length = longestCommonSuffix(word, query)
            if suffix_length > max_suffix_length or (suffix_length == max_suffix_length and len(word) < len(wordsContainer[best_index]) or (len(word) == len(wordsContainer[best_index]) and i < best_index)):
                max_suffix_length = suffix_length
                best_index = i
        result.append(best_index)
    return result

def kth_smallest_amount(coins, k):
    coins.sort()
    amounts = []
    for coin in coins:
        for i in range(1, k // coin + 1):
            amounts.append(i * coin)
    return amounts[k - 1]

def mark_elements(nums, queries):
    n = len(nums)
    marked = [False] * n
    answer = []

    for index, k in queries:
        if not marked[index]:
            marked[index] = True
            nums[index] = nums[index] - 1

            if k > 0:
                min_val = min(nums)
                min_indices = [i for i, x in enumerate(nums) if x == min_val and not marked[i]]

                for i in min_indices[:k]:
                    marked[i] = True
                    nums[i] = nums[i] - 1

            answer.append(sum(x for x in nums if not marked[x]))

    return answer

def sum_of_powers(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
                if i > 1:
                    dp[i][j] = (dp[i][j] + dp[i - 2][j - 1]) % MOD
                if j > 1:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] - dp[i - 2][j - 1]) % MOD

    return dp[n][k]

def max_sum_non_adjacent(nums):
    if not nums:
        return 0
    elif len(nums) == 1:
        return max(0, nums[0])

    dp = [0] * len(nums)
    dp[0] = max(0, nums[0])
    dp[1] = max(dp[0], max(0, nums[1]))

    for i in range(2, len(nums)):
        dp[i] = max(dp[i-1], dp[i-2] + max(0, nums[i]))

    return dp[-1]

def max_sum_non_adjacent_after_queries(nums, queries):
    MOD = 10**9 + 7

    for pos, x in queries:
        nums[pos] = x
        ans = max_sum_non_adjacent(nums)
        ans %= MOD

    return ans

def powerful_array(n):
    powers = []
    while n > 0:
        powers.append(1 << (n & -n))
        n -= 1
    return powers

def generate_big_nums(limit):
    big_nums = []
    i = 1
    while len(big_nums) < limit:
        powers = powerful_array(i)
        big_nums.extend(powers)
        i += 1
    return big_nums

def product_mod(queries):
    big_nums = generate_big_nums(10**15)
    answer = []
    for from_i, to_i, mod_i in queries:
        product = 1
        for i in range(from_i, to_i + 1):
            product = (product * big_nums[i]) % mod_i
        answer.append(product)
    return answer

def find_occurrences(nums, queries, x):
    occurrences = [i for i, num in enumerate(nums) if num == x]
    answer = []
    for q in queries:
        if q <= len(occurrences):
            answer.append(occurrences[q - 1])
        else:
            answer.append(-1)
    return answer
